import {
  mutation,
  query,
  object,
  string,
  number,
  type MutationContext,
  type QueryContext,
} from "apps";
import { always } from "apps/operations/approval";
type Read = QueryContext<{ drive: true }>;
type Write = MutationContext<{ drive: true }>;
const uploadInput = object({ upload: string(), cursor: number().optional() });
const continuation = (input: { upload: string; cursor?: number | undefined }) => ({
  upload: input.upload,
  ...(input.cursor === undefined ? {} : { cursor: input.cursor }),
});
export const attachmentTools = {
  fileInfo: query(
    {
      description: "Read a file's size and retained attachment identity at one pinned revision.",
      input: object({ path: string(), at: string().optional() }),
    },
    (ctx: Read, input) =>
      ctx.drive.info({ path: input.path, ...(input.at === undefined ? {} : { at: input.at }) }),
  ),
  beginAttachment: mutation(
    {
      description:
        "Reserve and resume an immutable attachment upload. Send only the missing one MiB parts. Follow next with cursor to list further missing parts.",
      approval: always(),
      input: object({
        operation: string(),
        oid: string(),
        bytes: number(),
        cursor: number().optional(),
      }),
    },
    (ctx: Write, input) =>
      ctx.drive.beginAttachment({
        operation: input.operation,
        oid: input.oid,
        bytes: input.bytes,
        ...(input.cursor === undefined ? {} : { cursor: input.cursor }),
      }),
  ),
  uploadAttachmentPart: mutation(
    {
      description:
        "Store one exact attachment part. Repeating it after a lost reply never uploads different bytes.",
      approval: always(),
      input: object({ upload: string(), part: number(), contentBase64: string() }),
    },
    (ctx: Write, input) => ctx.drive.uploadAttachmentPart(input),
  ),
  completeAttachment: mutation(
    {
      description:
        "Verify up to sixteen MiB of an upload. Follow next with cursor until present. Only a complete SHA-256 match can be attached to a path.",
      approval: always(),
      input: uploadInput,
    },
    (ctx: Write, input) => ctx.drive.completeAttachment(continuation(input)),
  ),
  cancelAttachment: mutation(
    {
      description:
        "Cancel an unaccepted upload and reclaim a bounded page of parts. Follow next until null. Accepted bytes are never deleted.",
      approval: always(),
      input: uploadInput,
    },
    (ctx: Write, input) => ctx.drive.cancelAttachment(continuation(input)),
  ),
  attachFile: mutation(
    {
      description:
        "Save a verified attachment at a vault path against an exact Git base. Concurrent edits keep both versions for review.",
      approval: always(),
      input: object({
        base: string(),
        path: string(),
        operation: string(),
        oid: string(),
        bytes: number(),
      }),
    },
    (ctx: Write, input) => ctx.drive.attach(input),
  ),
};

import { query, object, array, string, number, jsonSchema, type QueryContext } from "apps";
type Read = QueryContext<{ drive: true }>;
export const changeTools = {
  changes: query(
    {
      description:
        "Read only file changes between pinned cloud versions. Start from null for first download, then follow next until null.",
      input: object({
        from: jsonSchema({ type: ["string", "null"] }),
        to: string(),
        cursor: object({
          from: jsonSchema({ type: ["string", "null"] }),
          to: string(),
          frames: array(object({ name: string(), after: string() })),
        }).optional(),
        limit: number().optional(),
      }),
    },
    (ctx: Read, input) => {
      const from = input.from;
      if (from !== null && typeof from !== "string")
        throw new TypeError("Expected a revision or null");
      const cursor = input.cursor;
      let continuation;
      if (cursor) {
        const from = cursor.from;
        if (from !== null && typeof from !== "string")
          throw new TypeError("Expected a cursor revision or null");
        continuation = { ...cursor, from };
      }
      return ctx.drive.changes({
        from,
        to: input.to,
        ...(continuation ? { cursor: continuation } : {}),
        ...(input.limit === undefined ? {} : { limit: input.limit }),
      });
    },
  ),
};

import {
  mutation,
  query,
  object,
  array,
  string,
  number,
  boolean,
  jsonSchema,
  type MutationContext,
  type QueryContext,
} from "apps";
import { always } from "apps/operations/approval";
type Read = QueryContext<{ drive: true }>;
type Write = MutationContext<{ drive: true }>;
const identity = object({ id: string() });
export const importTools = {
  importStatus: query(
    {
      description:
        "Read the vault's counted initial import, including confirmed files, removed source files and its separate operation allowance.",
      input: object({ id: string().optional() }),
    },
    (ctx: Read, input) => ctx.drive.importStatus(input.id === undefined ? {} : { id: input.id }),
  ),
  planImport: mutation(
    {
      description:
        "Declare up to 100 initial source files per stable page before uploading. The final page reserves a counted one-time allowance. Later final pages may amend unclaimed files or record removed source paths; prior pages remain immutable.",
      approval: always(),
      input: object({
        id: string(),
        page: number(),
        entries: array(object({ path: string(), kind: string(), bytes: number(), hash: string() })),
        removed: array(string()).optional(),
        final: boolean(),
      }),
    },
    (ctx: Write, input) =>
      ctx.drive.planImport({
        ...input,
        entries: input.entries.map((entry) => {
          if (entry.kind !== "note" && entry.kind !== "attachment")
            throw new TypeError("Invalid initial import file kind");
          return { ...entry, kind: entry.kind };
        }),
        ...(input.removed === undefined ? {} : { removed: input.removed }),
      }),
  ),
  importRequest: mutation(
    {
      description:
        "Run a manifest-bound initial import request using its reserved allowance. Only import uploads and reconciliation reads are accepted. Every retry and storage operation is counted.",
      approval: always(),
      input: object({ id: string(), request: jsonSchema({ type: "object" }) }),
    },
    (ctx: Write, input) => {
      if (
        input.request === null ||
        typeof input.request !== "object" ||
        Array.isArray(input.request)
      )
        throw new TypeError("Invalid initial import request");
      return ctx.drive.runImport({
        id: input.id,
        request: Object.fromEntries(Object.entries(input.request)),
      });
    },
  ),
  finishImport: mutation(
    {
      description:
        "Close the one-time allowance after every declared file has a confirmed saved version or an explicit removed-source record. Unspent credit is released; counted usage and files are retained.",
      approval: always(),
      input: identity,
    },
    (ctx: Write, input) => ctx.drive.finishImport(input),
  ),
};

import { attachmentTools } from "./attachments.ts";
import { importTools } from "./imports.ts";
import { changeTools } from "./changes.ts";
import {
  array,
  defineApp,
  jsonSchema,
  mutation,
  number,
  object,
  query,
  router,
  string,
  type MutationContext,
  type QueryContext,
} from "apps";
import { always } from "apps/operations/approval";

export const requirements = { drive: true } as const;
type Read = QueryContext<typeof requirements>;
type Write = MutationContext<typeof requirements>;
const listCursor = object({ at: string(), path: string(), after: string() });
const searchCursor = object({
  at: string(),
  query: string(),
  frames: array(object({ path: string(), after: string() })),
  pending: object({ path: string(), offset: number(), line: number(), tail: string() }).optional(),
});
const file = object({
  path: string(),
  at: string().optional(),
  offset: number().optional(),
  maxBytes: number().optional(),
});
const readInput = (input: {
  path: string;
  at?: string | undefined;
  offset?: number | undefined;
  maxBytes?: number | undefined;
}) => ({
  path: input.path,
  ...(input.at === undefined ? {} : { at: input.at }),
  ...(input.offset === undefined ? {} : { offset: input.offset }),
  ...(input.maxBytes === undefined ? {} : { maxBytes: input.maxBytes }),
});
const write = object({ base: string(), path: string(), content: string(), operation: string() });
const applyNotes = mutation(
  {
    description:
      "Apply 1 to 100 text changes atomically against one exact cloud revision. Reuse the operation id after an unknown reply.",
    approval: always(),
    input: object({
      base: string(),
      operation: string(),
      edits: array(object({ path: string(), content: jsonSchema({ type: ["string", "null"] }) })),
    }),
  },
  (ctx: Write, input) =>
    ctx.drive.apply({
      ...input,
      edits: input.edits.map((edit) => {
        if (edit.content !== null && typeof edit.content !== "string")
          throw new TypeError("Batch content must be text or null");
        return { ...edit, content: edit.content };
      }),
    }),
);
const listNotes = query(
  {
    description:
      "List this vault's cloud notes and folders at one pinned version. Pass the returned next cursor to continue. Devices may be off.",
    input: object({
      path: string().optional(),
      at: string().optional(),
      cursor: listCursor.optional(),
      limit: number().optional(),
    }),
  },
  (ctx: Read, input) =>
    ctx.drive.list({
      ...(input.path === undefined ? {} : { path: input.path }),
      ...(input.at === undefined ? {} : { at: input.at }),
      ...(input.cursor === undefined ? {} : { cursor: input.cursor }),
      ...(input.limit === undefined ? {} : { limit: input.limit }),
    }),
);
const readNote = query(
  {
    description:
      "Read up to 256 KiB of a cloud note. Continue with offset=next and the same at; null next means complete.",
    input: file,
  },
  (ctx: Read, input) => ctx.drive.read(readInput(input)),
);
const searchNotes = query(
  {
    description:
      "Search the complete cloud vault. Follow cursor until complete is true; each page has a bounded scan budget.",
    input: object({
      query: string(),
      at: string().optional(),
      cursor: searchCursor.optional(),
      limit: number().optional(),
      maxFiles: number().optional(),
    }),
  },
  (ctx: Read, input) =>
    ctx.drive.search({
      query: input.query,
      ...(input.at === undefined ? {} : { at: input.at }),
      ...(input.cursor === undefined ? {} : { cursor: input.cursor }),
      ...(input.limit === undefined ? {} : { limit: input.limit }),
      ...(input.maxFiles === undefined ? {} : { maxFiles: input.maxFiles }),
    }),
);
const readAttachment = query(
  {
    description:
      "Read up to 64 KiB of a cloud attachment as base64. Continue with offset=next and the same at; null next means complete.",
    input: file,
  },
  (ctx: Read, input) => ctx.drive.attachment(readInput(input)),
);
const operationStatus = query(
  {
    description:
      "Recover a saved, landed or conflicting operation after an unknown reply. Reuse the original operation id.",
    input: object({ operation: string() }),
  },
  (ctx: Read, input) => ctx.drive.receipt(input),
);
const resolveConflict = mutation(
  {
    description:
      "Save reviewed conflict choices with both Git parents. Exact main and writer heads must still match. Null content deletes that path.",
    approval: always(),
    input: object({
      ref: string(),
      expected: string(),
      main: string(),
      edits: array(object({ path: string(), content: jsonSchema({ type: ["string", "null"] }) })),
      operation: string(),
    }),
  },
  (ctx: Write, input) =>
    ctx.drive.resolve({
      ...input,
      edits: input.edits.map((edit) => {
        if (edit.content !== null && typeof edit.content !== "string")
          throw new TypeError("Conflict content must be text or null");
        return { ...edit, content: edit.content };
      }),
    }),
);
const history = query(
  {
    description: "Read retained cloud versions and both parents of merged edits.",
    input: object({ at: string().optional(), limit: number().optional() }),
  },
  (ctx: Read, input) =>
    ctx.drive.history({
      ...(input.at === undefined ? {} : { at: input.at }),
      ...(input.limit === undefined ? {} : { limit: input.limit }),
    }),
);
const createNote = mutation(
  {
    description:
      "Create a cloud note without replacing an existing path. Supply the base from list/read and reuse operation unchanged on retry. Conflicts preserve the saved branch.",
    approval: always(),
    input: write,
  },
  (ctx: Write, input) => ctx.drive.write({ ...input, mode: "create" }),
);
const editNote = mutation(
  {
    description:
      "Edit an existing note from its read base. Git combines clean concurrent edits and preserves conflicts for review.",
    approval: always(),
    input: write,
  },
  (ctx: Write, input) => ctx.drive.write({ ...input, mode: "edit" }),
);
const moveNote = mutation(
  {
    description:
      "Move a cloud note while refusing an existing destination. Its old versions remain in history.",
    approval: always(),
    input: object({ base: string(), from: string(), to: string(), operation: string() }),
  },
  (ctx: Write, input) => ctx.drive.move(input),
);
const deleteNote = mutation(
  {
    description: "Remove a note from the current vault while retaining its history.",
    approval: always(),
    input: object({ base: string(), path: string(), operation: string() }),
  },
  (ctx: Write, input) => ctx.drive.remove(input),
);
const restoreVersion = mutation(
  {
    description:
      "Restore a historical note as a new edit at base. This preserves intervening history.",
    approval: always(),
    input: object({ base: string(), from: string(), path: string(), operation: string() }),
  },
  (ctx: Write, input) => ctx.drive.restore(input),
);
export default defineApp(requirements, {
  tools: router({
    ...changeTools,
    ...importTools,
    ...attachmentTools,
    applyNotes,
    listNotes,
    readNote,
    readAttachment,
    operationStatus,
    resolveConflict,
    searchNotes,
    history,
    createNote,
    editNote,
    moveNote,
    deleteNote,
    restoreVersion,
  }),
});

import { json, type Schema } from "apps";
import { createAppClient, queryReference, type OperationReference } from "apps/client";
import type { Devices, ImportStatus, Version } from "./model.ts";

export interface Entry {
  readonly name: string;
  readonly path: string;
  readonly kind: "file" | "directory";
  readonly oid: string;
}
export interface ListPage {
  readonly at: string;
  readonly path: string;
  readonly exists: boolean;
  readonly entries: readonly Entry[];
  readonly next: unknown;
}
export interface ReadResult {
  readonly at: string;
  readonly path: string;
  readonly bytes: number;
  readonly next: number | null;
  readonly content: string;
}
export interface Match {
  readonly path: string;
  readonly line: number;
  readonly excerpt: string;
}
interface SearchPage {
  readonly at: string;
  readonly matches: readonly Match[];
  readonly complete: boolean;
  readonly cursor: unknown;
}

const client = createAppClient();
// The tools return their drive results unchanged; the page reads them as those shapes.
const as = <T>() => json() as unknown as Schema<T, boolean>;
// Some tools (device check-ins, dated per-note history) arrive with a later server, so tools are
// named at runtime and answer with the shape this page expects or fail.
const reference = <T>(tool: string) =>
  queryReference<never>(tool as never) as unknown as OperationReference<object, T, "query">;
const call = <T>(tool: string, input: object): Promise<T> =>
  client.query(reference<T>(tool), input, as<T>());

/** Page through one folder of the vault at a pinned version. */
async function list(path: string | undefined): Promise<{ at: string | null; entries: Entry[] }> {
  const entries: Entry[] = [];
  let cursor: unknown;
  let at: string | null = null;
  for (let page = 0; page < 20; page++) {
    const result: ListPage = await call<ListPage>("listNotes", {
      ...(path === undefined ? {} : { path }),
      ...(at === null ? {} : { at }),
      ...(cursor === undefined ? {} : { cursor }),
      limit: 500,
    });
    at = result.at;
    entries.push(...result.entries);
    if (result.next === null || result.next === undefined) break;
    cursor = result.next;
  }
  return { at, entries };
}

/** Up to 1 MiB of a note: the reader shows text, not attachments. */
async function read(path: string, at?: string): Promise<string | null> {
  let content = "";
  let offset = 0;
  for (let page = 0; page < 4; page++) {
    const result = await call<ReadResult | null>("readNote", {
      path,
      ...(at === undefined ? {} : { at }),
      ...(offset === 0 ? {} : { offset }),
    });
    if (result === null) return page === 0 ? null : content;
    content += result.content;
    if (result.next === null) break;
    offset = result.next;
  }
  return content;
}

/** Text matches across the vault; each page scans a bounded number of files, so follow a few. */
async function search(query: string): Promise<Match[]> {
  const matches: Match[] = [];
  let cursor: unknown;
  let at: string | undefined;
  for (let page = 0; page < 8 && matches.length < 50; page++) {
    const result: SearchPage = await call<SearchPage>("searchNotes", {
      query,
      limit: 50,
      maxFiles: 50,
      ...(at === undefined ? {} : { at }),
      ...(cursor === undefined || cursor === null ? {} : { cursor }),
    });
    at = result.at;
    matches.push(...result.matches);
    if (result.complete || result.cursor === null) break;
    cursor = result.cursor;
  }
  return matches.slice(0, 50);
}

/** Every path in the vault, for wikilink resolution and the file count. Bounded for huge vaults. */
async function walk(limit = 20000): Promise<string[]> {
  const paths: string[] = [];
  const folders: (string | undefined)[] = [undefined];
  while (folders.length && paths.length < limit) {
    const { entries } = await list(folders.shift());
    for (const entry of entries)
      if (entry.kind === "directory") folders.push(entry.path);
      else paths.push(entry.path);
  }
  return paths;
}

interface AttachmentPage {
  readonly contentBase64: string;
  readonly next: number | null;
}
const maxAttachmentBytes = 8 * 1024 * 1024;

async function attachment(path: string, type: string): Promise<Blob | null> {
  const parts: Uint8Array<ArrayBuffer>[] = [];
  let offset = 0;
  while (offset < maxAttachmentBytes) {
    const page = await call<AttachmentPage | null>("readAttachment", {
      path,
      ...(offset === 0 ? {} : { offset }),
    });
    if (page === null) return null;
    const bytes = Uint8Array.from(atob(page.contentBase64), (char) => char.charCodeAt(0));
    parts.push(bytes);
    if (page.next === null) return new Blob(parts, { type });
    offset = page.next;
  }
  return null;
}

export const vault = {
  walk,
  attachment,
  importStatus: () => call<ImportStatus | null>("importStatus", {}).catch(() => null),
  list,
  read,
  search,
  /** Vault-wide when path is omitted. Servers without per-note history reject `path`. */
  history: async (input: { path?: string; at?: string; limit: number }): Promise<Version[] | null> => {
    try {
      const result = await call<unknown>("history", input);
      return Array.isArray(result) ? (result as Version[]) : null;
    } catch {
      return null;
    }
  },
  /** Device check-ins arrive with a later server and plugin; until then this is null. */
  devices: () => call<Devices>("devices", {}).catch(() => null),
};
export type VaultApi = typeof vault;

import { useCallback, useEffect, useMemo, useState } from "react";
import type { Entry, Match, VaultApi } from "./api.ts";
import { vaultState, noteTitle, type Devices, type ImportStatus, type Version } from "./model.ts";
import { Reader } from "./reader.tsx";
import { Summary } from "./summary.tsx";
import { Tree } from "./tree.tsx";

interface Loaded {
  readonly status: ImportStatus | null;
  readonly root: readonly Entry[];
  readonly latest: Version | null;
  readonly devices: Devices | null;
}

export function App({ api }: { readonly api: VaultApi }) {
  const [loaded, setLoaded] = useState<Loaded | "failed" | null>(null);
  const [files, setFiles] = useState<readonly string[]>([]);
  const [selected, setSelected] = useState<string | null>(null);
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    let cancelled = false;
    setLoaded(null);
    Promise.all([api.importStatus(), api.list(undefined), api.history({ limit: 1 }), api.devices()])
      .then(([status, root, history, devices]) => {
        if (cancelled) return;
        setLoaded({ status, root: root.entries, latest: history?.[0] ?? null, devices });
        // Wikilinks resolve against every path; the tree itself loads folder by folder.
        api.walk().then((paths) => !cancelled && setFiles(paths), () => undefined);
      })
      .catch(() => !cancelled && setLoaded("failed"));
    return () => {
      cancelled = true;
    };
  }, [api, attempt]);

  if (loaded === null) return <p className="page-message">Loading your vault…</p>;
  if (loaded === "failed")
    return (
      <div className="page-message">
        <p>Couldn't load the vault.</p>
        <button type="button" className="btn" onClick={() => setAttempt((value) => value + 1)}>
          Try again
        </button>
      </div>
    );
  const now = Date.now();
  const state = vaultState({
    status: loaded.status,
    hasFiles: loaded.root.length > 0,
    latest: loaded.latest,
    devices: loaded.devices,
    now,
  });
  if (state.kind === "empty") return <EmptyVault />;
  return (
    <div className={`vault ${selected === null ? "" : "has-note"}`}>
      <Summary
        name={loaded.devices?.vault.name ?? "Your vault"}
        state={state}
        files={files.length || null}
        latest={loaded.latest}
        devices={loaded.devices}
        now={now}
      />
      <div className="browser">
        <aside className="side">
          <Search api={api} files={files} onSelect={setSelected} />
          <Tree api={api} root={loaded.root} selected={selected} onSelect={setSelected} />
        </aside>
        {selected === null ? (
          <div className="reader placeholder">
            <p className="muted">Choose a note to read it.</p>
          </div>
        ) : (
          <Reader
            api={api}
            path={selected}
            files={files}
            devices={loaded.devices}
            onOpen={setSelected}
            onBack={() => setSelected(null)}
          />
        )}
      </div>
    </div>
  );
}

function EmptyVault() {
  return (
    <div className="empty">
      <h1>No vault connected yet</h1>
      <p>
        Choose Connect Obsidian at the top of this page to keep a vault here. Your agents can then
        read, search and edit your notes, even with every device off.
      </p>
      <ol className="steps">
        <li>
          <b>Start with your Mac</b>
          <span>It has every note, so it imports the vault.</span>
        </li>
        <li>
          <b>Approve in your browser</b>
          <span>Obsidian opens, then asks you to approve the device here.</span>
        </li>
        <li>
          <b>Add your phone later</b>
          <span>Choose Connect another device on this page.</span>
        </li>
      </ol>
    </div>
  );
}

/** Names match instantly from the vault's paths; text matches come from the server. */
function Search({
  api,
  files,
  onSelect,
}: {
  readonly api: VaultApi;
  readonly files: readonly string[];
  readonly onSelect: (path: string) => void;
}) {
  const [query, setQuery] = useState("");
  const [text, setText] = useState<readonly Match[] | "loading" | "failed">([]);
  const trimmed = query.trim();
  useEffect(() => {
    if (trimmed.length < 2) return setText([]);
    let cancelled = false;
    setText("loading");
    const timer = setTimeout(() => {
      api.search(trimmed).then(
        (matches) => !cancelled && setText(matches),
        () => !cancelled && setText("failed"),
      );
    }, 300);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [api, trimmed]);
  const names = useMemo(() => {
    const needle = trimmed.toLowerCase();
    return needle.length < 1 ? [] : files.filter((path) => path.toLowerCase().includes(needle)).slice(0, 20);
  }, [files, trimmed]);
  const pick = useCallback(
    (path: string) => {
      onSelect(path);
      setQuery("");
    },
    [onSelect],
  );
  const textMatches = Array.isArray(text) ? text.filter((match) => !names.includes(match.path)) : [];
  return (
    <div className="search">
      <input
        type="search"
        placeholder="Search notes"
        aria-label="Search notes"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />
      {trimmed.length > 0 && (
        <ul className="results">
          {names.map((path) => (
            <li key={`name:${path}`}>
              <button type="button" onClick={() => pick(path)}>
                <span className="label">{noteTitle(path.split("/").pop() ?? path)}</span>
                <span className="excerpt">{path}</span>
              </button>
            </li>
          ))}
          {textMatches.map((match) => (
            <li key={`text:${match.path}:${match.line}`}>
              <button type="button" onClick={() => pick(match.path)}>
                <span className="label">{noteTitle(match.path.split("/").pop() ?? match.path)}</span>
                <span className="excerpt">{match.excerpt}</span>
              </button>
            </li>
          ))}
          {text === "loading" && <li className="muted">Searching…</li>}
          {text === "failed" && <li className="muted">Search didn't finish. Try again.</li>}
          {Array.isArray(text) && trimmed.length >= 2 && names.length + textMatches.length === 0 && (
            <li className="muted">No notes match.</li>
          )}
        </ul>
      )}
    </div>
  );
}

/** In-page targets for wikilinks and embeds; hash links survive react-markdown's URL filter. */
export const noteHref = (path: string) => `#note=${encodeURIComponent(path)}`;
export const fileHref = (path: string) => `#file=${encodeURIComponent(path)}`;

export function linkTarget(
  href: string | undefined,
): { readonly kind: "note" | "file"; readonly path: string } | null {
  const match = href?.match(/^#(note|file)=(.+)$/);
  if (!match) return null;
  try {
    return { kind: match[1] as "note" | "file", path: decodeURIComponent(match[2]!) };
  } catch {
    return null;
  }
}

const imageTypes: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
  svg: "image/svg+xml",
  avif: "image/avif",
  bmp: "image/bmp",
};
export const imageType = (path: string) =>
  imageTypes[path.split(".").pop()?.toLowerCase() ?? ""] ?? null;

