/**
 * What the vault page shows, derived only from what the server has. Plugins before device
 * check-in leave `devices` null and history without times; the page then shows less, never an
 * empty or "connect" state for a vault that has synced.
 */

export interface ImportStatus {
  readonly state: "planning" | "ready" | "complete";
  readonly files: number;
  readonly confirmed: number;
  readonly omitted: number;
}

export interface Device {
  readonly connection: string;
  readonly agent: string | null;
  readonly name: string;
  readonly lastSyncAt: string | null;
  readonly pluginVersion: string | null;
}

export interface Devices {
  readonly vault: { readonly name: string | null };
  readonly devices: readonly Device[];
}

export type Author =
  | { readonly kind: "device"; readonly connection: string }
  | { readonly kind: "agent"; readonly name: string }
  | { readonly kind: "import" }
  | null;

export interface Version {
  readonly oid: string;
  readonly parents: readonly string[];
  readonly message: string;
  /** Absent before the server recorded commit times. */
  readonly time?: string;
  readonly author?: Author;
}

export type VaultState =
  | { readonly kind: "empty" }
  | { readonly kind: "importing"; readonly confirmed: number; readonly files: number }
  | { readonly kind: "stuck"; readonly confirmed: number; readonly files: number; readonly since: string | null }
  | { readonly kind: "up-to-date"; readonly files: number | null }
  | { readonly kind: "behind"; readonly files: number | null }
  | { readonly kind: "saved"; readonly files: number | null };

/** A device that hasn't synced for this long during an unfinished import counts as stuck. */
export const stuckAfterMs = 10 * 60 * 1000;

export function vaultState(input: {
  readonly status: ImportStatus | null;
  /** Whether the vault's root lists anything. */
  readonly hasFiles: boolean;
  readonly latest: Version | null;
  readonly devices: Devices | null;
  readonly now: number;
}): VaultState {
  const { status, devices, latest, now } = input;
  const files = status === null ? null : status.confirmed + status.omitted;
  if (status !== null && status.state !== "complete") {
    const synced = (devices?.devices ?? [])
      .map((device) => (device.lastSyncAt === null ? Number.NaN : Date.parse(device.lastSyncAt)))
      .filter((time) => !Number.isNaN(time));
    const last = synced.length ? Math.max(...synced) : null;
    // Without check-ins there is no clock to judge by, so an unfinished import reads as moving.
    if (devices !== null && (last === null || now - last > stuckAfterMs))
      return {
        kind: "stuck",
        confirmed: status.confirmed,
        files: status.files,
        since: last === null ? null : new Date(last).toISOString(),
      };
    return { kind: "importing", confirmed: status.confirmed, files: status.files };
  }
  if (status === null && !input.hasFiles && latest === null) return { kind: "empty" };
  const latestTime = latest?.time === undefined ? null : Date.parse(latest.time);
  if (devices === null || devices.devices.length === 0 || latestTime === null)
    return { kind: "saved", files };
  const allFetched = devices.devices.every(
    (device) => device.lastSyncAt !== null && Date.parse(device.lastSyncAt) >= latestTime,
  );
  return { kind: allFetched ? "up-to-date" : "behind", files };
}

/** Old plugins register every device under one client name; number them in connection order. */
export function deviceLabels<T extends { readonly name: string | null }>(
  devices: readonly T[],
): string[] {
  const counts = new Map<string, number>();
  for (const device of devices) {
    const name = device.name ?? "";
    counts.set(name, (counts.get(name) ?? 0) + 1);
  }
  const seen = new Map<string, number>();
  return devices.map((device) => {
    const name = device.name?.trim() || "Obsidian device";
    if ((counts.get(device.name ?? "") ?? 0) < 2) return name;
    const index = (seen.get(name) ?? 0) + 1;
    seen.set(name, index);
    return `${name} ${index}`;
  });
}

export function authorLabel(author: Author | undefined, devices: Devices | null): string {
  if (author === undefined || author === null) return "Unknown";
  if (author.kind === "agent") return author.name;
  if (author.kind === "import") return "Imported";
  return devices?.devices.find((device) => device.connection === author.connection)?.name ?? "A device";
}

const minute = 60 * 1000;
const hour = 60 * minute;
const day = 24 * hour;

/** "just now", "4 minutes ago", "3 hours ago", then a date. */
export function ago(iso: string, now: number): string {
  const time = Date.parse(iso);
  if (Number.isNaN(time)) return "";
  const elapsed = Math.max(0, now - time);
  if (elapsed < minute) return "just now";
  if (elapsed < hour) {
    const minutes = Math.floor(elapsed / minute);
    return `${minutes} minute${minutes === 1 ? "" : "s"} ago`;
  }
  if (elapsed < day) {
    const hours = Math.floor(elapsed / hour);
    return `${hours} hour${hours === 1 ? "" : "s"} ago`;
  }
  return new Date(time).toLocaleDateString(undefined, { day: "numeric", month: "short" });
}

export function when(iso: string): string {
  const time = new Date(iso);
  return time.toLocaleString(undefined, {
    day: "numeric",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  });
}

export const isNote = (path: string) => /\.md$/i.test(path);
export const noteTitle = (name: string) => name.replace(/\.md$/i, "");

/** Quartz Explorer's order: folders first, then names, case-insensitively and numerically. */
export const sortEntries = <T extends { readonly kind: "file" | "directory"; readonly name: string }>(
  entries: readonly T[],
): T[] =>
  [...entries].sort(
    (a, b) =>
      (a.kind === b.kind ? 0 : a.kind === "directory" ? -1 : 1) ||
      a.name.localeCompare(b.name, undefined, { sensitivity: "base", numeric: true }),
  );

import { useEffect, useMemo, useState, type ReactNode } from "react";
import Markdown, { type Components } from "react-markdown";
import remarkGfm from "remark-gfm";
import remarkCallout from "@r4ai/remark-callout";
import remarkWikiLink from "@flowershow/remark-wiki-link";
import { noteHref, fileHref, linkTarget } from "./links.ts";

/**
 * Obsidian-flavoured Markdown, read-only: the dashboard's renderer (react-markdown + GFM, raw HTML
 * skipped) plus Flowershow's wikilink resolution and Obsidian callouts. Links between notes stay
 * inside this page; embedded images load from the vault.
 */
export function NoteMarkdown({
  content,
  files,
  onOpen,
  loadFile,
}: {
  readonly content: string;
  /** Every vault path, so `[[note]]` resolves by Obsidian's shortest-path rule. */
  readonly files: readonly string[];
  readonly onOpen: (path: string) => void;
  readonly loadFile: (path: string) => Promise<Blob | null>;
}) {
  const plugins = useMemo(
    () => [
      remarkGfm,
      remarkCallout,
      [
        remarkWikiLink,
        {
          format: "shortestPossible",
          files: [...files],
          urlResolver: ({ filePath, isEmbed }: { filePath: string; isEmbed: boolean }) =>
            isEmbed ? fileHref(filePath) : noteHref(filePath),
        },
      ] as const,
    ],
    [files],
  );
  const components = useMemo<Components>(
    () => ({
      a: ({ href, children, className }) => {
        const target = linkTarget(href);
        if (target?.kind === "note")
          return (
            <a
              href={href}
              className={className?.includes("new") ? "wikilink missing" : "wikilink"}
              onClick={(event) => {
                event.preventDefault();
                if (!className?.includes("new")) onOpen(target.path);
              }}
            >
              {children}
            </a>
          );
        const safe = href !== undefined && /^https?:\/\//i.test(href) ? href : undefined;
        return safe === undefined ? (
          <span>{children}</span>
        ) : (
          <a href={safe} target="_blank" rel="noopener noreferrer">
            {children}
          </a>
        );
      },
      img: ({ src, alt, width }) => {
        const target = linkTarget(typeof src === "string" ? src : undefined);
        if (target?.kind === "file")
          return <VaultImage path={target.path} alt={alt ?? ""} width={width} load={loadFile} />;
        return <span className="embed-missing">{alt || "Image"}</span>;
      },
      iframe: ({ src }) => <EmbedChip src={src} />,
      video: ({ src }) => <EmbedChip src={src} />,
      audio: ({ src }) => <EmbedChip src={src} />,
    }),
    [onOpen, loadFile],
  );
  return (
    <div className="prose">
      <Markdown remarkPlugins={plugins as never} skipHtml components={components}>
        {content}
      </Markdown>
    </div>
  );
}

function EmbedChip({ src }: { readonly src?: string | undefined }): ReactNode {
  const target = linkTarget(src);
  const name = target?.path.split("/").pop() ?? "Attachment";
  return <span className="embed-chip">{name}</span>;
}

/** Images up to 8 MiB load from the vault; anything else shows its name. */
function VaultImage({
  path,
  alt,
  width,
  load,
}: {
  readonly path: string;
  readonly alt: string;
  readonly width?: string | number | undefined;
  readonly load: (path: string) => Promise<Blob | null>;
}) {
  const [url, setUrl] = useState<string | null | undefined>(undefined);
  useEffect(() => {
    let cancelled = false;
    let made: string | null = null;
    load(path)
      .then((blob) => {
        if (cancelled) return;
        made = blob === null ? null : URL.createObjectURL(blob);
        setUrl(made);
      })
      .catch(() => !cancelled && setUrl(null));
    return () => {
      cancelled = true;
      if (made !== null) URL.revokeObjectURL(made);
    };
  }, [path, load]);
  if (url === undefined) return <span className="embed-loading" aria-label={`Loading ${alt}`} />;
  if (url === null) return <span className="embed-chip">{path.split("/").pop()}</span>;
  return <img src={url} alt={alt} width={width} className="embed-image" />;
}

import { useCallback, useEffect, useState } from "react";
import type { VaultApi } from "./api.ts";
import { imageType } from "./links.ts";
import { authorLabel, when, isNote, noteTitle, type Devices, type Version } from "./model.ts";
import { NoteMarkdown } from "./note-markdown.tsx";

type Load<T> = { readonly kind: "loading" } | { readonly kind: "failed" } | { readonly kind: "ready"; readonly value: T };

function useLoad<T>(load: () => Promise<T>, key: string): [Load<T>, () => void] {
  const [state, setState] = useState<Load<T>>({ kind: "loading" });
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    let cancelled = false;
    setState({ kind: "loading" });
    load()
      .then((value) => !cancelled && setState({ kind: "ready", value }))
      .catch(() => !cancelled && setState({ kind: "failed" }));
    return () => {
      cancelled = true;
    };
    // `key` names everything `load` reads, so a new closure alone doesn't reload.
  }, [key, attempt]);
  return [state, () => setAttempt((value) => value + 1)];
}

/** Versions only count as per-note history when the server dates them. */
const datedVersions = (versions: Version[] | null) =>
  versions !== null && versions.every((version) => typeof version.time === "string")
    ? versions
    : null;

export function Reader({
  api,
  path,
  files,
  devices,
  onOpen,
  onBack,
}: {
  readonly api: VaultApi;
  readonly path: string;
  readonly files: readonly string[];
  readonly devices: Devices | null;
  readonly onOpen: (path: string) => void;
  readonly onBack: () => void;
}) {
  const [view, setView] = useState<"note" | "history">("note");
  const [version, setVersion] = useState<Version | null>(null);
  useEffect(() => {
    setView("note");
    setVersion(null);
  }, [path]);
  const [versions] = useLoad(
    () => api.history({ path, limit: 50 }).then(datedVersions),
    `history:${path}`,
  );
  const [content, retry] = useLoad(
    () => (isNote(path) ? api.read(path, version?.oid) : Promise.resolve(null)),
    `read:${path}:${version?.oid ?? ""}`,
  );
  const loadFile = useCallback(
    async (file: string) => {
      const type = imageType(file);
      return type === null ? null : api.attachment(file, type);
    },
    [api],
  );
  const parts = path.split("/");
  const name = parts.pop() ?? path;
  const dated = versions.kind === "ready" ? versions.value : null;
  const current = dated?.[0];
  return (
    <article className="reader">
      <header className="reader-head">
        <button type="button" className="back" onClick={onBack}>
          ‹ {parts.at(-1) ?? "Vault"}
        </button>
        {parts.length > 0 && <p className="crumb">{parts.join(" / ")}</p>}
        <h2 className="title">{isNote(name) ? noteTitle(name) : name}</h2>
        {current?.time !== undefined && (
          <p className="meta">
            Changed {when(current.time)} · {authorLabel(current.author, devices)}
          </p>
        )}
        {isNote(path) && (
          <div className="seg" role="tablist">
            <button type="button" role="tab" aria-selected={view === "note"} onClick={() => setView("note")}>
              Note
            </button>
            <button type="button" role="tab" aria-selected={view === "history"} onClick={() => setView("history")}>
              History{dated !== null ? ` · ${dated.length}` : ""}
            </button>
          </div>
        )}
      </header>
      <div className="reader-body">
        {!isNote(path) ? (
          <FilePreview path={path} load={loadFile} />
        ) : view === "history" ? (
          <History
            versions={versions}
            devices={devices}
            onPick={(picked) => {
              setVersion(picked.oid === current?.oid ? null : picked);
              setView("note");
            }}
          />
        ) : (
          <>
            {version !== null && (
              <div className="banner">
                <span>
                  You're reading the version from {when(version.time ?? "")}, by{" "}
                  {authorLabel(version.author, devices)}.
                </span>
                <button type="button" className="btn sm" onClick={() => setVersion(null)}>
                  Back to current
                </button>
              </div>
            )}
            {content.kind === "loading" ? (
              <p className="muted">Loading…</p>
            ) : content.kind === "failed" ? (
              <p className="muted">
                Couldn't load this note.{" "}
                <button type="button" className="link" onClick={retry}>
                  Try again
                </button>
              </p>
            ) : content.value === null ? (
              <p className="muted">This note isn't in the vault any more.</p>
            ) : (
              <NoteMarkdown content={content.value} files={files} onOpen={onOpen} loadFile={loadFile} />
            )}
          </>
        )}
      </div>
    </article>
  );
}

function History({
  versions,
  devices,
  onPick,
}: {
  readonly versions: Load<Version[] | null>;
  readonly devices: Devices | null;
  readonly onPick: (version: Version) => void;
}) {
  if (versions.kind === "loading") return <p className="muted">Loading…</p>;
  if (versions.kind === "failed" || versions.value === null)
    return <p className="muted">Versions of this note appear after the next Signalbox update.</p>;
  if (versions.value.length === 0) return <p className="muted">No saved versions yet.</p>;
  return (
    <ol className="versions">
      {versions.value.map((version, index) => (
        <li key={version.oid}>
          <button type="button" onClick={() => onPick(version)}>
            <span className={`pip ${index === 0 ? "current" : ""}`} aria-hidden />
            <span className="who">
              {authorLabel(version.author, devices)}
              {version.author?.kind === "agent" && <span className="tag">Agent</span>}
              {index === 0 && <span className="tag">Current</span>}
            </span>
            <span className="t">{when(version.time ?? "")}</span>
          </button>
        </li>
      ))}
    </ol>
  );
}

function FilePreview({
  path,
  load,
}: {
  readonly path: string;
  readonly load: (path: string) => Promise<Blob | null>;
}) {
  const [url, setUrl] = useState<string | null | undefined>(undefined);
  useEffect(() => {
    let made: string | null = null;
    let cancelled = false;
    setUrl(undefined);
    load(path)
      .then((blob) => {
        if (cancelled) return;
        made = blob === null ? null : URL.createObjectURL(blob);
        setUrl(made);
      })
      .catch(() => !cancelled && setUrl(null));
    return () => {
      cancelled = true;
      if (made !== null) URL.revokeObjectURL(made);
    };
  }, [path, load]);
  if (url === undefined) return <p className="muted">Loading…</p>;
  if (url === null) return <p className="muted">This file can't be shown here. Open it in Obsidian.</p>;
  return <img src={url} alt={path.split("/").pop()} className="embed-image" />;
}

/* The dashboard's tokens, so the vault reads as part of the same product. */
:root {
  color-scheme: light;
  --font-sans: "Geist", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Geist Mono", ui-monospace, "SF Mono", Menlo, monospace;
  --background: #fff;
  --foreground: #111;
  --primary: #0a0a0a;
  --primary-foreground: #fff;
  --muted: #fafafa;
  --muted-foreground: #666;
  --accent: #f5f5f5;
  --destructive: #b4261a;
  --warning: #99651a;
  --success: #1a7f37;
  --border: #eaeaea;
  --input: #d4d4d4;
  --ring: #888;
  --link: #6d4fd6;
}
@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --background: #0a0a0a;
    --foreground: #ededed;
    --primary: #fff;
    --primary-foreground: #0a0a0a;
    --muted: #111;
    --muted-foreground: #9a9a9a;
    --accent: #1a1a1a;
    --destructive: #e0726a;
    --warning: #d6aa65;
    --success: #4cb86a;
    --border: #242424;
    --input: #333;
    --ring: #777;
    --link: #a48bff;
  }
}
* { box-sizing: border-box; }
html, body, #root { margin: 0; height: 100%; }
body {
  font: 14px/1.5 var(--font-sans);
  letter-spacing: -0.011em;
  background: var(--background);
  color: var(--foreground);
  -webkit-font-smoothing: antialiased;
}
button { font: inherit; color: inherit; background: none; border: 0; padding: 0; text-align: left; }
button:not(:disabled) { cursor: pointer; }
:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }
.muted { color: var(--muted-foreground); font-size: 13px; }
.link { text-decoration: underline; text-underline-offset: 2px; }
.btn { display: inline-flex; align-items: center; height: 36px; padding: 0 12px; border: 1px solid var(--input); border-radius: 6px; font-size: 13px; font-weight: 500; white-space: nowrap; }
.btn.sm { height: 30px; font-size: 12px; padding: 0 10px; }
.page-message { padding: 48px 28px; color: var(--muted-foreground); display: grid; gap: 12px; justify-items: start; }

.vault { display: flex; flex-direction: column; height: 100%; }

/* Summary */
.summary { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 420px); gap: 32px; padding: 20px 28px; border-bottom: 1px solid var(--border); }
.summary > .min-w-0 { min-width: 0; }
.vault-name { margin: 0 0 4px; font-size: 15px; font-weight: 600; }
.health { margin: 0; display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; font-size: 13px; color: var(--muted-foreground); }
.health .part::before { content: "·"; margin-right: 8px; color: var(--input); }
.state { display: inline-flex; align-items: center; gap: 6px; font-weight: 500; color: var(--foreground); }
.dot { width: 8px; height: 8px; border-radius: 99px; flex-shrink: 0; }
.dot.ok { background: var(--success); }
.dot.warn { background: var(--warning); }
.dot.busy { border: 2px solid var(--muted-foreground); border-right-color: transparent; width: 10px; height: 10px; }
.progress { margin-top: 12px; max-width: 520px; }
.bar { height: 4px; border-radius: 99px; background: var(--accent); overflow: hidden; }
.bar i { display: block; height: 100%; background: var(--foreground); }
